fn transpose(arr: Vec<Vec<i8>>) -> Vec<Vec<i8>> {
    // Number of rows in the original matrix
    let m = arr.len();
    // Number of columns in the original matrix (assume at least one row)
    let n = arr[0].len();

    // Create a new matrix with dimensions n x m, initialized to zeroes
    let mut transposed = vec![vec![0i8; m]; n];

    // Fill in the transposed matrix
    for i in 0..m {
        for j in 0..n {
            transposed[j][i] = arr[i][j];
        }
    }

    transposed
}

